import { Controller, Get, Injectable, Module } from "@nestjs/common"

@Injectable()
class CounterService {
    private count = 0
    increment() {
        return ++this.count
    }
}

@Controller("a")
class AController {
    constructor(private counter: CounterService) {}
    @Get() hit() { return { from: "A", count: this.counter.increment() } }
}

@Controller("b")
class BController {
    constructor(private counter: CounterService) {}
    @Get() hit() { return { from: "B", count: this.counter.increment() } }
}

@Module({ controllers: [AController, BController], providers: [CounterService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/a")
    await http.get("/b")
    await http.get("/a")
    console.log("Ikkala controller ham BITTA servis nusxasini ishlatadi (singleton)")
    await http.close()
}
main()

