import { Body, Controller, Get, Injectable, Module, Param, ParseIntPipe, Patch, Post } from "@nestjs/common"

@Injectable()
class TodosService {
    private todos: { id: number; title: string; done: boolean }[] = []
    add(title: string) { const t = { id: this.todos.length + 1, title, done: false }; this.todos.push(t); return t }
    all() { return this.todos }
    toggle(id: number) { const t = this.todos.find(x => x.id === id)!; t.done = !t.done; return t }
}

@Controller("todos")
class TodosController {
    constructor(private readonly todos: TodosService) {}
    @Post() add(@Body("title") title: string) { return this.todos.add(title) }
    @Get() all() { return this.todos.all() }
    @Patch(":id/toggle") toggle(@Param("id", ParseIntPipe) id: number) { return this.todos.toggle(id) }
}

@Module({ controllers: [TodosController], providers: [TodosService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/todos", { title: "Non olish" })
    await http.post("/todos", { title: "Dars qilish" })
    await http.patch("/todos/1/toggle", {})
    await http.get("/todos")
    await http.close()
}
main()

examples.output:
POST /todos → 201 {"id":1,"title":"Non olish","done":false}
POST /todos → 201 {"id":2,"title":"Dars qilish","done":false}
PATCH /todos/1/toggle → 200 {"id":1,"title":"Non olish","done":true}
GET /todos → 200 [{"id":1,"title":"Non olish","done":true},{"id":2,"title":"Dars qilish","done":false}]

