import { Body, Controller, Delete, Get, Module, Param, Patch, Post, Put } from "@nestjs/common"

const db = new Map<number, { title: string; done: boolean }>()
let seq = 0
@Controller("todos") class T {
    @Get() all() { return [...db].map(([id, t]) => ({ id, ...t })) }
    @Post() add(@Body("title") title: string) { const id = ++seq; db.set(id, { title, done: false }); return { id } }
    @Put(":id") replace(@Param("id") id: string, @Body() b: { title: string; done: boolean }) { db.set(+id, b); return db.get(+id) }
    @Patch(":id") done(@Param("id") id: string) { db.get(+id)!.done = true; return db.get(+id) }
    @Delete(":id") remove(@Param("id") id: string) { return { deleted: db.delete(+id) } }
}
@Module({ controllers: [T] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/todos", { title: "Non olish" })
    await http.post("/todos", { title: "Kod yozish" })
    await http.patch("/todos/1")
    await http.put("/todos/2", { title: "NestJS o'rganish", done: false })
    await http.delete("/todos/1")
    await http.get("/todos")
    await http.close()
}
main()

