function toCurl(method: string, url: string, body?: object, headers: Record<string, string> = {}) {
    const parts = [`curl -X ${method} "${url}"`]
    for (const [k, v] of Object.entries(headers)) parts.push(`-H "${k}: ${v}"`)
    if (body) parts.push(`-H "Content-Type: application/json"`, `-d '${JSON.stringify(body)}'`)
    return parts.join(" \\\n  ")
}
console.log(toCurl("POST", "http://localhost:3000/orders", { item: "non", qty: 2 }, { Authorization: "Bearer <token>" }))

